// Literary scenes split from the original ordered BEATS list; preserve saved IDs.
pub const BEATS_PART_3: &[Beat] = &[
    Beat {id:"redhare",title:"赤兔旧主",chapter:3,act:0,hero:Some(Hero::LuBu),prerequisite:None,flag:"red_hare",character:"丁原、李肃、董卓",premise:"毛评第三回写何进召外兵、董卓擅议废立、李肃以赤兔金珠诱吕布杀丁原；嘉靖本第五回详录四路召兵诏书，第六回叙杀丁原。《三国志》卷七记董卓诱布杀原、布斩首归卓，另记吕布有赤兔，却不证赠马是杀原条件。",vow:"架空抉择：分栏记丁原遇害、小说献马诱杀与史传未证动机",bargain:"架空抉择：只取赤兔功名，抹去丁原及旧部责任",reward_card:"blood_courage",reward_gold:25,reward_heal:0},
    Beat {id:"pavilion",title:"凤仪亭风波",chapter:8,act:0,hero:Some(Hero::LuBu),prerequisite:Some("red_hare"),flag:"phoenix_pavilion",character:"王允、貂蝉、董卓、李儒",premise:"董卓宴上处死张温，王允为除暴与貂蝉商议连环计：先许吕布，后献董卓。李儒曾劝董卓赐金帛缓和父子猜忌，直至凤仪亭掷戟才彻底撕破表面和睦。原著本回董卓未死；今日如何回应权术与私欲？",vow:"克制私怨，记下权臣暴虐与无辜者处境",bargain:"只图私欲，趁乱夺取府中金帛",reward_card:"huaji",reward_gold:26,reward_heal:2},
    Beat {id:"changan",title:"长安余烬",chapter:9,act:0,hero:Some(Hero::LuBu),prerequisite:Some("phoenix_pavilion"),flag:"changan_account",character:"王允、士孙瑞、李肃、蔡邕、李傕、郭汜、贾诩",premise:"王允联吕布诛董，李肃以禅位之辞诱董入朝；可杀一人未必能定天下。蔡邕因哭董下狱，王允又拒赦旧部，贾诩劝李傕郭汜合兵来犯。长安终陷，王允殒命，吕布失城。今日记下这段治理失败之账，还是只取诛董的战功？",vow:"记下拒赦与失城之责，救护城中逃亡百姓",bargain:"夸耀刺董功名，转卖城防军粮",reward_card:"blood_courage",reward_gold:18,reward_heal:6},
    Beat {id:"xiaopei",title:"小沛寄军与徐州旧约",chapter:13,act:0,hero:Some(Hero::LuBu),prerequisite:Some("changan_account"),flag:"xiaopei_refuge",character:"陈宫、刘备、糜竺、关羽、张飞",premise:"定陶败后袁绍已遣颜良助曹，陈宫劝吕布改投新领徐州的刘备。刘备出城迎客并再三让州印，吕布见关张怒色未敢接受；酒席上张飞因「贤弟」称呼发怒，刘备劝止。吕布欲离，刘备让其驻小沛并许军粮。昔日长安失守，今得寄军之地，如何守住主客之分？",vow:"约束部曲、守小沛客军之分，记下刘备供粮旧恩",bargain:"逼取徐州州印，换得眼前军资",reward_card:"hold_line",reward_gold:22,reward_heal:6},
    Beat {id:"halberd",title:"辕门一箭",chapter:16,act:1,hero:Some(Hero::LuBu),prerequisite:Some("phoenix_pavilion"),flag:"halberd_shot",character:"刘备、纪灵",premise:"诛董之后，李傕郭汜攻破长安，吕布亲见勇武难补朝局。如今辕门一箭为刘备与纪灵暂止兵戈；这一次能否把威名变成可持续的信任？",vow:"解围止战",bargain:"以箭威索粮",reward_card:"huaji",reward_gold:35,reward_heal:8},
    Beat {id:"seven_armies",title:"七路军书与反戈之约",chapter:17,act:1,hero:Some(Hero::LuBu),prerequisite:Some("halberd_shot"),flag:"seven_armies_account",character:"袁术、陈登、韩暹、杨奉、刘备、关羽",premise:"辕门射戟暂解刘备之围，袁术却以玉玺僭号并发七路兵讨徐州。陈登劝韩暹、杨奉反戈，吕布分兵五路破敌，关羽亦截袁术败军；但韩杨后来纵兵掠民，被刘备诛杀。射戟止战与临时盟友反戈，不能抹去后续军纪之责。",vow:"保存七路军书与韩杨军纪，约束反戈之军不扰民",bargain:"只取破袁战利，隐去韩杨扰民的后果",reward_card:"hold_line",reward_gold:14,reward_heal:5},
    Beat {id:"xiaopei_courier",title:"小沛密书与杀使之戒",chapter:18,act:1,hero:Some(Hero::LuBu),prerequisite:Some("seven_armies_account"),flag:"xiaopei_courier_guard",character:"陈宫、陈珪、陈登、刘备、简雍、高顺、张辽",premise:"七路军破后，陈珪父子与曹操的联系未断。陈宫截获刘备回曹操的密书，吕布在原著中杀使，分兵袭小沛；高顺、张辽进兵，关羽劝张飞莫轻追张辽。前番辕门止兵与七路军纪若要作数，今日面对密使与百姓又该如何抉择？",vow:"架空抉择：留使者性命，核查密书并预警小沛居民",bargain:"照原著杀使举兵，只取截获军书的战利",reward_card:"hold_line",reward_gold:12,reward_heal:7},
    Beat {id:"xiapi_orders",title:"下邳军令与侯成之冤",chapter:19,act:1,hero:Some(Hero::LuBu),prerequisite:Some("xiaopei_courier_guard"),flag:"xiapi_orders_account",character:"陈宫、严氏、貂蝉、侯成、宋宪、魏续",premise:"小沛败后陈登设火号使吕布与陈宫互相误击，徐州、小沛相继失守。下邳被围，陈宫建议分兵掎角、截曹军粮道，吕布因顾虑家室迟疑；袁术要求先送女再救兵，吕布背女突围不成。曹军决沂泗之水后，侯成追回失马、献酒请示却遭鞭打，宋宪魏续遂谋献城。军令和猜疑的代价须分开记账。",vow:"架空抉择：留下陈宫谏言、侯成受罚与守城军民的完整记录",bargain:"只报将士不忠，隐去主帅拒谏与重罚的前因",reward_card:"hold_line",reward_gold:18,reward_heal:5},
    Beat {id:"whitegate",title:"白门楼残雪",chapter:19,act:2,hero:Some(Hero::LuBu),prerequisite:Some("halberd_shot"),flag:"white_gate",character:"陈宫、曹操",premise:"长安失守的旧账延至下邳：陈宫劝分兵、断粮不成；曹军决沂泗水围下邳，侯成追回失马献酒遭重罚，遂与宋宪魏续合谋献门缚吕布。高顺沉默就刑，陈宫拒降而曹操安排照顾其家，刘备以丁原、董卓旧事劝曹操处死吕布；张辽痛骂曹操，救者是谁留待第二十回。白门楼并非吕布亲自破围战死，架空玩家选择不改变小说结局。",vow:"在残卷中承认拒谏、重罚与背盟的责任",bargain:"架空选择：只记武勇不认军令旧账",reward_card:"tianxia",reward_gold:40,reward_heal:10},
    Beat {id:"maicheng",title:"麦城粮断",chapter:76,act:2,hero:Some(Hero::GuanYu),prerequisite:Some("jingzhou_warning"),flag:"maicheng_supply",character:"徐晃、糜芳、傅士仁",premise:"旧日轻慢积成后方疑惧。麦城粮使带回空囊：不只是江防失察，旧部信任也已经断裂。",vow:"先遣使安抚旧部与百姓",bargain:"严令催粮、强攻突围",reward_card:"hold_line",reward_gold:30,reward_heal:6},
    Beat {id:"yiling_bridge",title:"八阵渡火",chapter:84,act:2,hero:Some(Hero::SunShangxiang),prerequisite:Some("river_divide"),flag:"yiling_bridge",character:"陆逊、刘备、吴班",premise:"江边火光照出旧日截江的裂隙。陆逊识破诱敌之兵，七百里营寨终成灰烬；旧盟只剩救人的余地。",vow:"开放渡口收容双方伤兵",bargain:"乘胜截取蜀军粮船",reward_card:"qiaoying",reward_gold:34,reward_heal:11},
    Beat {id:"jieting_debt",title:"街亭违令",chapter:95,act:2,hero:Some(Hero::ZhugeLiang),prerequisite:Some("successor_scroll"),flag:"jieting_accountability",character:"马谡、王平、司马懿",premise:"马谡弃道路屯山，王平劝谏不从。知兵书并不等于知兵情；受托之后，该如何承担用人之失？",vow:"保存王平军报、追究军令责任",bargain:"掩盖误判以保军心",reward_card:"kongcheng",reward_gold:16,reward_heal:9},
    Beat {id:"imperial_jade",title:"井中玉玺",chapter:6,act:0,hero:None,prerequisite:None,flag:"jade_whisper",character:"孙坚、程普、袁绍、刘表",premise:"毛评第006回、嘉靖第011—012回均写董卓焚洛阳、孙坚修宗庙后于井中打捞妇人遗体，从锦囊朱匣中得印；袁绍追问并致书刘表截归途；嘉靖第011回李傕求亲还说华雄曾误冲撞孙坚，毛评本省此语。《三国志》卷46陈寿正文记孙坚修陵，得传国玺的井中细节来自裴注《吴书》，裴注又收录质疑及裴松之反驳，不能断言传国玺已被史实确证。玩家只决定保存证词，不改原著孙坚藏玺。",vow:"登记两版求亲措辞、井中印匣来源与裴注争议，保留民命和宗庙账",bargain:"只报得玺祥瑞，隐去迁都死难、证据分歧与私藏争端",reward_card:"zhentu",reward_gold:17,reward_heal:2},
    Beat {id:"changban",title:"长坂遗袍",chapter:41,act:0,hero:None,prerequisite:None,flag:"changban_pledge",character:"赵云、糜夫人、刘备",premise:"阵中小小襁褓比千军更沉。护一人，可能失去一城。",vow:"先护百姓",bargain:"绕阵劫粮",reward_card:"yidong",reward_gold:8,reward_heal:10},
    Beat {id:"mandate",title:"衣带密诏",chapter:20,act:1,hero:None,prerequisite:Some("jade_whisper"),flag:"edict_secret",character:"献帝、伏皇后、伏完、董承、王子服、种辑、吴硕、吴子兰、马腾",premise:"许田射鹿后曹操越位受贺，献帝忧惧，伏完建议以衣带暗传血诏。伏皇后将密诏缝入玉带衬里，董承出宫遭曹操盘查却未被发现；夜间灯花烧破衬里才见血字。王子服先假称告发，后与种辑、吴硕、吴子兰、马腾盟誓。第020回末马腾只提议再邀一位刘氏宗亲，第021回才明确刘备入盟。传国玉玺与衣带诏是两件不同的小说器物。",vow:"架空抉择：保存密诏来源、结盟人名与传递风险",bargain:"架空抉择：焚诏取赏，掩去衣带密约",reward_card:"qimou",reward_gold:18,reward_heal:0},
    Beat {id:"south_wilds",title:"七擒之约",chapter:90,act:2,hero:None,prerequisite:None,flag:"seven_captures",character:"孟获、诸葛亮",premise:"南中七次围困之后，信服不是束缚。刀兵可折，民心不可强取。",vow:"释俘安边",bargain:"席卷山寨",reward_card:"tiebi",reward_gold:10,reward_heal:12},
    Beat {id:"empty_city",title:"空城余弦",chapter:95,act:2,hero:None,prerequisite:None,flag:"empty_city",character:"司马懿、诸葛亮、马谡",premise:"街亭失守，空城仍有琴声。用谋诈敌的前提，是摸清对手知己知彼的弱点。",vow:"守静示虚",bargain:"以险搏功",reward_card:"qimou",reward_gold:15,reward_heal:6},
    Beat {id:"wooden_ox",title:"木牛流马",chapter:102,act:2,hero:None,prerequisite:Some("empty_city"),flag:"wooden_ox",character:"诸葛亮、司马懿",premise:"连年征伐，走不动的不是战马，而是断续的粮道。运粮机关正待破局。",vow:"修整运输机关",bargain:"拆售机关换金",reward_card:"caochuan",reward_gold:25,reward_heal:8},
    Beat {id:"jin_unification",title:"三分归一",chapter:120,act:2,hero:None,prerequisite:Some("jade_whisper"),flag:"jin_epilogue",character:"杜预、孙皓、司马炎",premise:"一方古玺的传闻走到末章，权柄终归新姓。英雄们的誓愿是否还有继承者？",vow:"藏起史书以待后人",bargain:"送旧玺入新府",reward_card:"zonghenggong",reward_gold:40,reward_heal:4},
];
